import sys
import re

def evaluate_expression(expr, variables):
    # Replace variable names with their values
    for name in variables:
        expr = expr.replace(name, str(variables[name]))

    # Tokenize the expression
    tokens = re.findall(r'(\d+|[+\-*/()]|[a-zA-Z_][a-zA-Z0-9_]*)', expr)
    tokens = [t for t in tokens if t.strip() != '']

    # Convert tokens to postfix notation (Reverse Polish Notation)
    output = []
    operators = []
    precedence = {'+': 1, '-': 1, '*': 2, '(': 0}

    for token in tokens:
        if token.isdigit():
            output.append(int(token))
        elif token in variables:
            output.append(variables[token])
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(':
                output.append(operators.pop())
            operators.pop()  # Remove '('
        else:  # Operator
            while (operators and operators[-1] != '(' and
                   precedence[operators[-1]] >= precedence[token]):
                output.append(operators.pop())
            operators.append(token)

    while operators:
        output.append(operators.pop())

    # Evaluate postfix expression
    stack = []
    for token in output:
        if isinstance(token, int):
            stack.append(token)
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)

    return stack[0] if stack else 0

def render_template(template_path):
    with open(template_path, 'r') as file:
        lines = file.readlines()

    variables = {}
    for line in lines:
        line = line.strip()
        if line.startswith('@'):
            # Parse variable definition
            parts = re.split(r'\s*=\s*', line[1:], 1)
            if len(parts) != 2:
                continue  # Skip malformed lines
            name = parts[0].strip()
            expr = parts[1].strip()
            # Remove surrounding whitespace from expr
            expr = re.sub(r'\s+', ' ', expr).strip()
            variables[name] = evaluate_expression(expr, variables)

    for line in lines:
        line = line.strip()
        if not line:
            continue
        if line.startswith('@'):
            continue
        # Replace placeholders
        rendered = line
        while True:
            placeholder_match = re.search(r'\{\{([^}]*)\}\}', rendered)
            if not placeholder_match:
                break
            expr = placeholder_match.group(1).strip()
            # Remove surrounding whitespace from expr
            expr = re.sub(r'\s+', ' ', expr).strip()
            value = evaluate_expression(expr, variables)
            rendered = rendered.replace(placeholder_match.group(0), str(value))
        print(rendered)

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print("Usage: python render_template.py <template_file>")
        sys.exit(1)
    render_template(sys.argv[1])

import sys
import re

def evaluate_expression(expr, variables):
    def parse_expression(tokens):
        tokens = [t for t in tokens if t != '']
        if not tokens:
            return None
        if tokens[0] == '(':
            sub_expr = tokens[1:-1]
            result = parse_expression(sub_expr)
            tokens = tokens[:-1]
            return result
        elif tokens[0] in variables:
            return variables[tokens[0]]
        elif tokens[0].isdigit():
            return int(tokens[0])
        else:
            raise ValueError(f"Unexpected token: {tokens[0]}")

    def evaluate(tokens):
        tokens = tokens.copy()
        while '*' in tokens:
            i = tokens.index('*')
            left = evaluate(tokens[:i])
            right = evaluate(tokens[i+1:])
            tokens = tokens[:i] + [str(left * right)] + tokens[i+2:]
        tokens = tokens.copy()
        while '+-' in tokens:
            i = tokens.index('+') if '+' in tokens else tokens.index('-')
            left = evaluate(tokens[:i])
            right = evaluate(tokens[i+1:])
            if tokens[i] == '+':
                tokens = tokens[:i] + [str(left + right)] + tokens[i+2:]
            else:
                tokens = tokens[:i] + [str(left - right)] + tokens[i+2:]
        return evaluate(tokens)

    tokens = re.findall(r'(\d+|[a-zA-Z_][a-zA-Z0-9_]*|[+\-*/()])', expr)
    return evaluate(tokens)

def main():
    if len(sys.argv) != 2:
        print("Usage: python render_template.py <template_file>", file=sys.stderr)
        sys.exit(1)

    template_file = sys.argv[1]
    variables = {}
    with open(template_file, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            if line.startswith('@'):
                parts = line.split('=', 1)
                if len(parts) != 2:
                    continue
                var_name = parts[0][1:].strip()
                expr = parts[1].strip()
                try:
                    value = evaluate_expression(expr, variables)
                    variables[var_name] = value
                except:
                    continue
            else:
                if '{{' in line and '}}' in line:
                    start = line.find('{{')
                    end = line.find('}}')
                    expr = line[start+2:end]
                    try:
                        value = evaluate_expression(expr, variables)
                        line = line[:start] + str(value) + line[end+2:]
                    except:
                        pass
                print(line)

if __name__ == "__main__":
    main()

